				hullWidth: hullWidths[type],
				circleDir: Math.random() < 0.5 ? 1 : -1,
				dashCooldown: 0,
			});

			// These don't count toward spawn quota — they're bonus enemies
			this.enemiesRemaining++;
			this.enemiesTotal++;
		}
	}

